from __future__ import annotations


def screeps_live_document(*, data_url: str = "/api/agent/screeps") -> str:
    document = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ferro Screeps Lab</title>
<meta name="description" content="Ferro's live Screeps laboratory: world state, agent strategy, bounded experiments, and learning outcomes.">
<link rel="canonical" href="https://livingruntime.com/screeps/">
<style>
:root{color-scheme:dark;background:#070a0d;color:#edf3f6;font-family:Inter,ui-sans-serif,system-ui,sans-serif;--line:#26313a;--muted:#8c9ba6;--ferro:#79d7b0;--enemy:#e28c86;--amber:#ddb971}
*{box-sizing:border-box}body{margin:0;background:#070a0d}.shell{width:min(1180px,calc(100% - 24px));margin:auto}.top{padding:24px 0 14px;display:flex;justify-content:space-between;gap:16px;align-items:flex-end;flex-wrap:wrap}.k{font:700 11px ui-monospace,monospace;letter-spacing:.14em;color:#738491}.top h1{margin:6px 0 0;font:500 clamp(34px,6vw,62px) Georgia,serif}.nav{display:flex;gap:12px;flex-wrap:wrap}.nav a{color:#b8c8d2;text-decoration:none;font-size:13px}.statusbar{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 16px}.pill{border:1px solid var(--line);border-radius:999px;padding:7px 10px;color:#b7c4cc;font-size:12px}.pill.live{border-color:rgba(121,215,176,.45);color:var(--ferro)}.pill.bad{border-color:rgba(226,140,134,.45);color:var(--enemy)}.grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.7fr);gap:14px}.card{border:1px solid var(--line);border-radius:16px;background:#0d1217;padding:14px;min-width:0}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:10px}.head h2{margin:0;font-size:17px}.stage{background:#05080a;border:1px solid #1d262d;border-radius:12px;overflow:hidden}.stage canvas{display:block;width:100%;aspect-ratio:2/1}.versus{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;margin-top:12px}.side{border:1px solid #202a31;border-radius:12px;padding:12px}.side.ferro{border-color:rgba(121,215,176,.3)}.side.enemy{border-color:rgba(226,140,134,.3)}.side b{display:block;font-size:15px}.side small{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:9px}.metric{background:#080d11;border-radius:8px;padding:8px}.metric b{font-size:14px}.metric span{display:block;color:#71808a;font-size:10px;margin-top:2px}.vs{color:#60707b;font:800 11px ui-monospace,monospace}.stack{display:grid;gap:14px}.rows{display:grid;gap:7px}.row{display:grid;grid-template-columns:110px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid #1c252b;font-size:12px}.row:last-child{border-bottom:0}.row span:first-child{color:#71808a}.row strong{overflow-wrap:anywhere}.strategy{display:grid;grid-template-columns:1fr 1fr;gap:8px}.strategy article{border:1px solid #202a31;border-radius:10px;padding:10px}.strategy h3{font-size:12px;margin:0 0 7px}.strategy p{font:11px/1.55 ui-monospace,monospace;color:#91a0aa;margin:0;white-space:pre-line}.history{margin-top:14px}.episode{display:grid;grid-template-columns:1.1fr .8fr .5fr .5fr;gap:8px;padding:9px 0;border-bottom:1px solid #1c252b;font-size:11px;align-items:center}.episode:last-child{border:0}.reward.pos{color:var(--ferro)}.reward.neg{color:var(--enemy)}.muted{color:var(--muted);font-size:12px;line-height:1.5}.legend{display:flex;gap:12px;flex-wrap:wrap;color:#8797a1;font-size:10px;margin-top:8px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:4px}.dot.f{background:var(--ferro)}.dot.e{background:var(--enemy)}.dot.n{background:#6f91b2}.empty{padding:18px;color:#75858f;text-align:center}
@media(max-width:850px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.episode{grid-template-columns:1fr 1fr}.episode span:nth-child(2){text-align:right}}@media(max-width:480px){.shell{width:calc(100% - 14px)}.top{padding-top:15px}.versus{grid-template-columns:1fr 1fr}.vs{display:none}.strategy{grid-template-columns:1fr}.stage canvas{aspect-ratio:1.5/1}}
</style></head><body><main class="shell">
<header class="top"><div><div class="k">FERRO · EXTERNAL COMPETITIVE WORLD</div><h1>Screeps Lab</h1></div><nav class="nav"><a href="/live/">Live</a><a href="/brain/">Brain Lab</a><a href="/neural/">Neural Life</a></nav></header>
<div class="statusbar"><span class="pill" id="run-status">LOADING</span><span class="pill" id="view-mode">view —</span><span class="pill" id="tick-status">tick —</span><span class="pill" id="tactical-status">tactical —</span><span class="pill" id="research-arm">research —</span><span class="pill" id="outcome">reward pending</span></div>
<div class="grid">
<section class="card"><div class="head"><h2>World state</h2><span class="muted" id="episode-id">no episode yet</span></div><div class="stage"><canvas id="world" width="1000" height="500" aria-label="Screeps world state"></canvas></div><div class="legend"><span><i class="dot f"></i>Ferro</span><span><i class="dot e"></i>Opponent</span><span><i class="dot n"></i>Neutral source</span><span>square = spawn · circle = creep</span></div>
<div class="versus"><article class="side ferro"><b>Ferro</b><small id="ferro-strategy-name">strategy —</small><div class="metrics" id="ferro-metrics"></div></article><div class="vs">VS</div><article class="side enemy"><b>Opponent</b><small id="enemy-strategy-name">opponent —</small><div class="metrics" id="enemy-metrics"></div></article></div></section>
<aside class="stack">
<section class="card"><div class="head"><h2>Playing state</h2><span class="k">LIVE</span></div><div class="rows" id="playing-state"></div></section>
<section class="card"><div class="head"><h2>Learning state</h2><span class="k">WORLD-GROUNDED</span></div><div class="rows" id="learning-state"></div></section>
<section class="card"><div class="head"><h2>Current strategies</h2></div><div class="strategy"><article><h3>FERRO</h3><p id="ferro-strategy"></p></article><article><h3>OPPONENT</h3><p id="enemy-strategy"></p></article></div></section>
</aside></div>
<section class="card history"><div class="head"><h2>Recent episodes</h2><span class="muted">real match outcome → reward → learning</span></div><div id="episodes"><div class="empty">No settled episodes yet.</div></div></section>
</main><script>
const $=id=>document.getElementById(id);const esc=x=>String(x==null?'—':x);let last=null;
function metric(v,l){return '<div class="metric"><b>'+esc(v)+'</b><span>'+l+'</span></div>'}
function strategyText(s){if(!s)return '—';return ['workers '+esc(s.worker_target),'builders '+esc(s.builder_target),'upgraders '+esc(s.upgrader_target),'soldiers '+esc(s.soldier_target),'aggression '+Number(s.aggression||0).toFixed(2),'reserve '+Number(s.reserve_energy||0).toFixed(2)].join('\n')}
function draw(frame){const c=$('world'),ctx=c.getContext('2d');const w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#05080a';ctx.fillRect(0,0,w,h);const gap=22,roomW=(w-gap)/2,roomH=h;for(let r=0;r<2;r++){const ox=r*(roomW+gap);ctx.strokeStyle='#172129';ctx.lineWidth=1;for(let i=0;i<=50;i+=5){const x=ox+i/50*roomW,y=i/50*roomH;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,roomH);ctx.stroke();ctx.beginPath();ctx.moveTo(ox,y);ctx.lineTo(ox+roomW,y);ctx.stroke()}ctx.fillStyle='#60717c';ctx.font='18px ui-monospace,monospace';ctx.fillText((frame&&frame.rooms&&frame.rooms[r])||('ROOM '+(r+1)),ox+10,24)}
if(!frame||!Array.isArray(frame.objects))return;for(const o of frame.objects){const roomIndex=frame.rooms&&frame.rooms.indexOf(o.room);if(roomIndex<0)continue;const ox=roomIndex*(roomW+gap),x=ox+(Number(o.x)+.5)/50*roomW,y=(Number(o.y)+.5)/50*roomH;const color=o.side==='ferro'?'#79d7b0':o.side==='opponent'?'#e28c86':'#6f91b2';ctx.fillStyle=color;ctx.strokeStyle=color;if(o.type==='spawn'){ctx.fillRect(x-6,y-6,12,12)}else if(o.type==='creep'){ctx.beginPath();ctx.arc(x,y,o.role==='soldier'?5:4,0,Math.PI*2);ctx.fill();if(o.role==='soldier'){ctx.strokeStyle='#f3d08b';ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.stroke()}}else if(o.type==='source'){ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill()}else if(o.type==='controller'){ctx.strokeRect(x-4,y-4,8,8)}}}
function setRows(id,rows){$(id).innerHTML=rows.map(([a,b])=>'<div class="row"><span>'+a+'</span><strong>'+esc(b)+'</strong></div>').join('')}
function render(d){last=d;const st=esc(d.status),vm=esc(d.display_mode||((d.playing===true||st==='RUNNING')?'LIVE':d.displaying_latest_replay?'LAST_REPLAY':d.frame?'LAST_RESULT':'NONE'));$('run-status').textContent=st;$('run-status').className='pill '+((d.playing===true||st==='RUNNING')?'live':st.includes('FAIL')?'bad':'');$('view-mode').textContent='view '+vm;$('view-mode').className='pill '+(vm==='LIVE'?'live':'');$('tick-status').textContent='tick '+esc(d.tick)+' / '+esc(d.ticks_requested);const rawResearch=d.research||{},rc=d.research_context||(rawResearch.arm?rawResearch:{}),research=rawResearch.arm?{}:rawResearch;$('research-arm').textContent='research '+esc(rc.arm||'IDLE');const rw=typeof d.reward==='number'?d.reward:null;$('outcome').textContent=(d.playing===true||st==='RUNNING')?'reward pending':rw==null?esc(d.winner||'waiting'):(esc(d.winner)+' · reward '+rw.toFixed(3));$('outcome').className='pill '+(rw!=null?(rw<0?'bad':'live'):'');$('episode-id').textContent=esc(d.episode_id);const f=d.frame||{},fs=f.ferro||{},os=f.opponent||{},ts=f.tactical||{};$('tactical-status').textContent='tactical '+esc(ts.mode||'—');$('tactical-status').className='pill '+(ts.mode==='WON'?'live':ts.mode==='DEFEATED'?'bad':'');$('ferro-metrics').innerHTML=metric(fs.creeps,'creeps')+metric(fs.soldiers,'soldiers')+metric(fs.energy,'energy')+metric(fs.spawn_alive?'UP':'DOWN','spawn');$('enemy-metrics').innerHTML=metric(os.creeps,'creeps')+metric(os.soldiers,'soldiers')+metric(os.energy,'energy')+metric(os.spawn_alive?'UP':'DOWN','spawn');$('ferro-strategy-name').textContent=esc(rc.strategy_id||'—');$('enemy-strategy-name').textContent=esc(rc.opponent_id||'—');$('ferro-strategy').textContent=strategyText(d.strategy);$('enemy-strategy').textContent=strategyText(d.opponent_strategy);const trial=research.prospective_trial||{};setRows('playing-state',[['runtime',st],['scheduler',d.scheduler_status||'READY'],['view',vm],['tactical mode',ts.mode||'—'],['momentum',ts.momentum||'—'],['force delta',ts.force_delta==null?'—':(Number(ts.force_delta)>0?'+':'')+ts.force_delta],['energy delta',ts.energy_delta==null?'—':(Number(ts.energy_delta)>0?'+':'')+ts.energy_delta],['Ferro raiders',ts.ferro_raiders||0],['enemy raiders',ts.opponent_raiders||0],['tick',esc(d.tick)+' / '+esc(d.ticks_requested)],['Ferro spawn',fs.spawn_alive===false?'DESTROYED':'alive'],['Opponent spawn',os.spawn_alive===false?'DESTROYED':'alive'],['frames',d.frames_recorded||0],['last update',d.age_seconds==null?'—':Number(d.age_seconds).toFixed(1)+'s ago']]);setRows('learning-state',[['research arm',rc.arm||'—'],['tested strategy',rc.strategy_id||'—'],['opponent',rc.opponent_id||'—'],['incumbent',research.incumbent_strategy_id||'—'],['generation',research.generation||0],['episodes',research.episode_count||0],['prospective trial',trial.status||'none'],['reward authority',d.function_success_is_reward?'FUNCTION':'WORLD ONLY']]);draw(f);const eps=(d.recent_episodes||[]).slice().reverse();$('episodes').innerHTML=eps.length?eps.map(x=>{const r=Number(x.reward||0);return '<div class="episode"><span>'+esc(x.strategy_id)+'</span><span>'+esc(x.opponent_id).replace('screeps-opponent:','vs ')+'</span><span>'+(Number(x.match_outcome||0)>0?'WIN':Number(x.match_outcome||0)<0?'LOSS':'DRAW')+'</span><span class="reward '+(r<0?'neg':'pos')+'">'+r.toFixed(3)+'</span></div>'}).join(''):'<div class="empty">No settled episodes yet.</div>'}
async function refresh(){try{const r=await fetch('__SCREEPS_DATA_URL__',{cache:'no-store'});if(!r.ok)throw new Error('status '+r.status);render(await r.json())}catch(e){$('run-status').textContent='UNAVAILABLE';$('run-status').className='pill bad'}}refresh();setInterval(refresh,1000);
</script></body></html>"""
    return document.replace("__SCREEPS_DATA_URL__", str(data_url))


__all__ = ["screeps_live_document"]
